CompletableFuture<String> cf = CompletableFuture.supplyAsync(() -> "SETTLED");

// ═══ get() — checked exceptions, needs try-catch ═══
try {
    String result = cf.get();  // blocks, returns result
} catch (InterruptedException e) {
    Thread.currentThread().interrupt();
} catch (ExecutionException e) {
    Throwable cause = e.getCause();  // original exception
}

// get() with timeout:
try {
    String result = cf.get(5, TimeUnit.SECONDS);  // timeout!
} catch (TimeoutException e) {
    log.warn("Timed out waiting for settlement");
}

// ═══ join() — unchecked, clean in lambdas ═══
String result = cf.join();  // blocks, returns result
// If cf failed: throws CompletionException (unchecked!)
// No try-catch needed!

// ═══ WHY join() is better in streams/lambdas ═══
List<CompletableFuture<String>> futures = List.of(cf1, cf2, cf3);

// With get(): ugly — lambda can't throw checked exceptions!
// futures.stream().map(f -> f.get()).toList();  → COMPILE ERROR!

// With join(): clean!
List<String> results = futures.stream()
    .map(CompletableFuture::join)  // no checked exception!
    .toList();
