package com.bank.getjoin;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class GetVsJoinTest {

    // ═══ get() — checked exceptions ═══
    @Test
    void get_checkedExceptions() throws ExecutionException, InterruptedException {
        CompletableFuture<String> cf = CompletableFuture.supplyAsync(() -> "SETTLED");
        String result = cf.get();  // must declare throws!
        assertThat(result).isEqualTo("SETTLED");
    }

    // ═══ get() — wraps in ExecutionException ═══
    @Test
    void get_wrapsInExecutionException() {
        CompletableFuture<String> cf = CompletableFuture.supplyAsync(() -> {
            throw new RuntimeException("DB down!");
        });
        assertThatThrownBy(cf::get)
            .isInstanceOf(ExecutionException.class)
            .hasCauseInstanceOf(RuntimeException.class);
    }

    // ═══ join() — unchecked CompletionException ═══
    @Test
    void join_uncheckedCompletionException() {
        CompletableFuture<String> cf = CompletableFuture.supplyAsync(() -> {
            throw new RuntimeException("DB down!");
        });
        assertThatThrownBy(cf::join)
            .isInstanceOf(CompletionException.class)
            .hasCauseInstanceOf(RuntimeException.class);
    }

    // ═══ join() — clean in streams ═══
    @Test
    void join_cleanInStreams() {
        List<CompletableFuture<String>> futures = List.of(
            CompletableFuture.supplyAsync(() -> "TRD-001"),
            CompletableFuture.supplyAsync(() -> "TRD-002"),
            CompletableFuture.supplyAsync(() -> "TRD-003")
        );

        List<String> results = futures.stream()
            .map(CompletableFuture::join)  // clean! No try-catch!
            .toList();

        assertThat(results).containsExactly("TRD-001", "TRD-002", "TRD-003");
    }

    // ═══ get() with timeout ═══
    @Test
    void get_withTimeout() {
        CompletableFuture<String> slow = CompletableFuture.supplyAsync(() -> {
            try { Thread.sleep(10000); } catch (InterruptedException e) { }
            return "done";
        });

        assertThatThrownBy(() -> slow.get(100, TimeUnit.MILLISECONDS))
            .isInstanceOf(TimeoutException.class);
    }

    // ═══ join() has NO timeout ═══
    @Test
    void join_noTimeout_useOrTimeout() {
        CompletableFuture<String> cf = CompletableFuture.supplyAsync(() -> "done");
        // join() blocks indefinitely — no timeout variant!
        // Workaround: cf.orTimeout(5, TimeUnit.SECONDS).join()  (Java 9)
        String result = cf.orTimeout(5, TimeUnit.SECONDS).join();
        assertThat(result).isEqualTo("done");
    }
}
